INSERT INTO "IMPORT Rebate True-ups" SELECT coalesce(k0."Customer Group", fpabench_error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY 1, 2, 3
ON CONFLICT ("Customer Group", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT Rebate True-ups";
